$ErrorActionPreference='Stop'
if(-not(Get-Command claude -ErrorAction SilentlyContinue)){Write-Host 'Claude Code not installed. Run: irm https://claude.ai/install.ps1 | iex   then paste this again.' -ForegroundColor Yellow;return}
$d="$env:USERPROFILE\.claude\icons";$i="$d\claude-code.ico";New-Item -ItemType Directory -Force $d|Out-Null
[IO.File]::WriteAllBytes($i,[Convert]::FromBase64String(''))
$s=$env:USERPROFILE;$k=New-Object -ComObject WScript.Shell
$l=$k.CreateShortcut("$([Environment]::GetFolderPath('Desktop'))\Claude Code.lnk")
if(Get-Command wt.exe -ErrorAction SilentlyContinue){$l.TargetPath="$env:WINDIR\System32\cmd.exe";$l.Arguments="/c start `"`" wt.exe -w new -p `"PowerShell`" -d `"$s`" powershell -NoExit -Command claude"}else{$l.TargetPath="$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe";$l.Arguments="-NoExit -Command claude"}
$l.WorkingDirectory=$s;$l.IconLocation="$i,0";$l.Save()
Write-Host 'Done. Right-click "Claude Code" on your Desktop > Show more options > Pin to taskbar.' -ForegroundColor Green
